class TreeNode:
    def __init__(self, val=0, left=None, right=None, next=None):
        self.val = val
        self.left = left
        self.right = right
        self.next = next


class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next


from typing import *

class Solution:
    def maxNumberOfFamilies(self, n: int, reservedSeats: List[List[int]]) -> int:
        # There are 10 seats per row: 1 to 10
        # A four-person group needs 4 adjacent seats in one row.
        # Possible positions for a 4-person group:
        # 1. Seats 2,3,4,5 (left block)
        # 2. Seats 4,5,6,7 (middle block)
        # 3. Seats 6,7,8,9 (right block)
        # Note: Seats 1 and 10 are not part of any 4-person group since they are at the edges.
        # The middle block (4,5,6,7) can be used if both left and right are blocked, but it overlaps with left and right.
        # Actually, the three possible groups are:
        # - Left: [2,3,4,5]
        # - Middle: [4,5,6,7]
        # - Right: [6,7,8,9]
        #
        # For each row, we can have at most 2 groups if no seats are reserved.
        # If some seats are reserved, we need to check which of the three blocks are still available.
        #
        # Key insight: 
        # - If left block [2,3,4,5] is free, we can place a group there.
        # - If right block [6,7,8,9] is free, we can place a group there.
        # - If both left and right are blocked, we can check if middle [4,5,6,7] is free.
        #
        # So for each row with reserved seats, we determine which blocks are available.
        # For rows without any reserved seats, we can always fit 2 groups (left and right).
        
        # Group reserved seats by row
        reserved_by_row = {}
        for row, seat in reservedSeats:
            if row not in reserved_by_row:
                reserved_by_row[row] = set()
            reserved_by_row[row].add(seat)
        
        # Total families = 2 * n initially (assuming all rows can have 2 groups)
        # But we need to subtract for rows that have reserved seats
        # Actually, let's think differently:
        # Start with 2 * n (each row can have 2 groups)
        # For each row that has reserved seats, we need to recalculate how many groups can be placed.
        # The number of groups for a row with reserved seats can be 0, 1, or 2.
        # So we subtract 2 for each such row, then add back the actual number of groups possible.
        
        total = 2 * n
        
        for row, reserved_seats in reserved_by_row.items():
            # Remove 2 from total for this row (since we initially counted 2)
            total -= 2
            
            # Check left block: seats 2,3,4,5
            left_free = not any(s in reserved_seats for s in [2, 3, 4, 5])
            # Check right block: seats 6,7,8,9
            right_free = not any(s in reserved_seats for s in [6, 7, 8, 9])
            # Check middle block: seats 4,5,6,7
            middle_free = not any(s in reserved_seats for s in [4, 5, 6, 7])
            
            if left_free and right_free:
                total += 2
            elif left_free or right_free:
                total += 1
            elif middle_free:
                total += 1
            # else: 0 groups, add 0
        
        return total

